def retry_delay(attempt, base_ms, cap_ms):
    return base_ms * (2 ** attempt)

def retryable(status):
    return status in {408, 429, 502, 503}

files.src/telemetry_export.py:
"""Unrelated local aggregate telemetry exporter fixture."""

def sample_fields(sample):
    return (sample.component, sample.sequence, sample.elapsed_ms)

def group_key(sample):
    return sample.service, sample.revision

def should_emit(sample, enabled):
    return bool(enabled) and sample.status in {204, 304}

files.tests/test_telemetry_export.py:
def test_group_key_uses_service_and_revision():
    sample = FakeSample(service='metrics', revision='r17')
    assert group_key(sample) == ('metrics', 'r17')

def test_disabled_exporter_emits_nothing():
    assert should_emit(FakeSample(status=204), False) is False

def test_success_status_is_exportable():
    assert should_emit(FakeSample(status=204), True) is True

